function bore(shape,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,Math.PI*2,false);shape.holes.push(p);}
function extrude(parent,s,depth,position,material,name){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth,bevelEnabled:false,curveSegments:40}),material,position,name);}
function adapter(host){
 const s=new THREE.Shape();s.moveTo(-6.4,21.8);s.lineTo(6.4,21.8);s.lineTo(10.4,17.8);s.lineTo(10.4,-7.65);s.lineTo(8,-7.65);s.absarc(8,-12,4.35,Math.PI/2,Math.PI*1.5,false);s.lineTo(10.4,-16.35);s.lineTo(10.4,-17.8);s.lineTo(6.4,-21.8);s.lineTo(5.6,-21.8);s.lineTo(5.6,-17.3);s.lineTo(-5.6,-17.3);s.lineTo(-5.6,-21.8);s.lineTo(-6.4,-21.8);s.lineTo(-10.4,-17.8);s.lineTo(-10.4,-16.35);s.lineTo(-8,-16.35);s.absarc(-8,-12,4.35,Math.PI*1.5,Math.PI*2.5,false);s.lineTo(-10.4,-7.65);s.lineTo(-10.4,17.8);s.closePath();bore(s,0,-12,1.8);for(const x of[-3,-1,1,3])bore(s,x,-16.6,.32);
 const pcb=extrude(host.body,s,.8,[0,0,-2.7],materials.plastic(0x3c5646,{roughness:.9}),'Finger physical adapter PCB with true retaining/Grove bores and boss reliefs');pcb.userData={role:'physical-pcb',installationInferred:true};
 const dark=materials.plastic(0x252925,{roughness:.85}),metal=materials.metal(0xb9b8aa,{roughness:.5}),ceramic=materials.plastic(0xb9aa7e,{roughness:.9}),regulator=slab(host.body,1.3,2.9,.9,.07,[5.8,-4.6,-1.9],dark,[],.01);regulator.name='Finger U1 HT7533 fixed three-terminal regulator';const regulatorLeads=[];for(const[dx,dy]of[[-.85,-.95],[-.85,.95],[.85,0]])regulatorLeads.push(mesh(host.body,new THREE.BoxGeometry(.65,.35,.16),metal,[5.8+dx,-4.6+dy,-1.8],'Finger HT7533 physical terminal'));
 const capacitors=[];for(const[n,x,y,w,h]of[['C1 100nF',-6,-5,1.2,.7],['C2 10uF',-3,-5,1.6,.9],['C3 10uF',0,-5,1.6,.9],['C4 100nF',3,-5,1.2,.7]]){const p=slab(host.body,w,h,.5,.05,[x,y,-1.9],ceramic,[],0);p.name='Finger fixed '+n;capacitors.push(p);for(const sign of[-1,1])mesh(host.body,new THREE.BoxGeometry(.2,h,.18),metal,[x+sign*(w/2-.07),y,-1.77],'Finger capacitor physical metal termination');}
 return{pcb,regulator,regulatorLeads,capacitors};
}
function pickup(host){
 const frame=new THREE.Group();frame.name='Finger fixed1020A capacitive module installation';frame.position.set(0,7.1,0);host.body.add(frame);const dark=materials.plastic(0x242b2b,{roughness:.82}),silver=materials.metal(0x9a9d94,{roughness:.48}),contacts=materials.metal(0xb8b5a0,{roughness:.5}),s=new THREE.Shape(),x=8.65,y=15;
 s.moveTo(-x+1.4,-y);s.lineTo(x-1.4,-y);s.lineTo(x,-y+1.4);s.lineTo(x,y-2.1);s.lineTo(x-2.1,y);s.lineTo(-x+2.1,y);s.lineTo(-x,y-2.1);s.lineTo(-x,-y+1.4);s.closePath();const pcb=extrude(frame,s,.8,[0,0,.1],materials.plastic(0x1b2a26,{roughness:.9}),'Finger linked1020A physical30×17.3mm chamfered module PCB');
 const carrier=slab(frame,14.6,15.2,2.55,1,[0,0,.9],dark,[],0);carrier.name='Finger fixed capacitive pickup package carrier';
 const ring=roundedRect(14.6,15.2,1);ring.holes.push(roundedRect(12.9,13.5,.35,{path:new THREE.Path(),clockwise:true}));const bezel=extrude(frame,ring,.35,[0,0,3.45],silver,'Finger physical metal contact bezel with real recessed face opening'),face=slab(frame,12.9,13.5,.3,.35,[0,0,3.45],materials.plastic(0x131b25,{roughness:.45,metalness:.08}),[],0);face.name='Finger fixed dark capacitive acquisition surface';face.userData={role:'physical-capacitive-face',part:'FPC1020A',activeCollectionMm:[8,8],scope:'Fixed surface only;no display,mechanical press,scan image or fingerprint state'};
 const processor=slab(frame,8.6,8.6,1.4,.1,[0,0,-1.3],dark,[],0);processor.name='Finger linked module fixed rear processor package,part marking not inferred';const processorLeads=[];for(let side=0;side<4;side++)for(let n=0;n<16;n++){const along=(n-7.5)*.5,edge=4.6,p=mesh(frame,new THREE.BoxGeometry(.25,.75,.14),contacts,[side===0?along:side===1?edge:side===2?-along:-edge,side===0?edge:side===1?-along:side===2?-edge:along,-.1],'Finger rear processor physical package lead');p.rotation.z=side*Math.PI/2;processorLeads.push(p);}
 const headerFrame=new THREE.Group();headerFrame.name='Finger internal fixed six-contact module header';headerFrame.position.set(0,12.6,-.6);frame.add(headerFrame);const white=materials.plastic(0xdedfd5,{roughness:.85});for(const sign of[-1,1])mesh(headerFrame,new THREE.BoxGeometry(.5,2,1.4),white,[sign*3.6,0,0],'Finger internal header side wall');mesh(headerFrame,new THREE.BoxGeometry(6.7,.5,1.4),white,[0,.75,0],'Finger internal header rear wall');mesh(headerFrame,new THREE.BoxGeometry(6.7,1.5,.3),white,[0,-.25,.55],'Finger internal header dielectric floor');const headerContacts=[];for(let n=0;n<6;n++)headerContacts.push(mesh(headerFrame,new THREE.BoxGeometry(.25,.9,.25),contacts,[(n-2.5)*1,0,-.1],'Finger internal module connector physical contact '+(n+1)));
 const minor=[];for(const[x,y]of[[-6,-5],[-6,1],[-6,6],[6,-6],[6,0],[6,6],[-3,11],[2,11]])minor.push(mesh(frame,new THREE.BoxGeometry(1.2,.65,.4),dark,[x,y,-.1],'Finger concealed module minor package,reconstructed placement'));
 return{frame,pcb,carrier,bezel,face,processor,processorLeads,headerFrame,headerContacts,minor};
}
function grove(host){
 const frame=new THREE.Group();frame.name='Finger physical cyan HY2.0-4P socket';frame.position.fromArray(spec.grove.position);frame.quaternion.copy(FACE.bottom);host.body.add(frame);const cyan=materials.plastic(spec.grove.color,{roughness:.72}),metal=materials.metal(0xb7b6a3,{roughness:.43}),box=(s,p,n,m=cyan)=>mesh(frame,new THREE.BoxGeometry(...s),m,p,'Finger Grove '+n),depth=6.1;
 for(const sign of[-1,1]){box([.65,5.2,depth],[sign*4.675,0,-depth/2],'side rail');box([.7,.6,3.2],[sign*3.85,2.3,-4.5],'inner guide');box([.6,.45,1.2],[sign*3.65,2.375,-1.8],'locking shoulder');}box([8.7,.65,depth],[0,-2.275,-depth/2],'floor');box([8.7,4.55,.65],[0,.325,-depth+.325],'deep dielectric rear wall');box([4.8,.45,2.3],[0,2.375,-4.3],'locking bridge');
 const contacts=[],tails=[];for(let i=0;i<4;i++){const x=(i-1.5)*2;contacts.push(box([.42,.42,4.3],[x,.2,-3.5],'real contact '+(i+1),metal));tails.push(box([.42,4.1,.42],[x,-1.65,-5.65],'descending solder tail '+(i+1),metal));tails.push(box([.42,.42,1.4],[x,-3.7,-6.35],'solder foot '+(i+1),metal));mesh(host.body,new THREE.CylinderGeometry(.22,.22,1,24).rotateX(Math.PI/2),metal,[x,-16.6,-2.3],'Finger Grove physical terminal through PCB solder bore');}
 const port=host.add(new Port({id:'grove',label:'PORT.C · UART · HY2.0-4P',connector:'grove',position:spec.grove.position,quaternion:portQuaternion('bottom'),hitSize:[10,1,5.2],pins:[{n:1,name:'GND',color:'black'},{n:2,name:'5V',color:'red'},{n:3,name:'UART_RX',color:'yellow'},{n:4,name:'UART_TX',color:'white'}],meta:{role:'visual-connector',face:'bottom',scope:'Physical connector,cable attachment and pose only;no UART,fingerprint,identity,touch wake,power,electrical or firmware behavior'}}));return{frame,contacts,tails,port};
}
function retaining(host){const metal=materials.metal(0xa1a597,{roughness:.5}),head=mesh(host.body,new THREE.CylinderGeometry(1.22,1.22,.5,48).rotateX(Math.PI/2),metal,[0,-12,-3.35],'Finger recessed physical retaining screw head'),shank=mesh(host.body,new THREE.CylinderGeometry(.6,.6,6,32).rotateX(Math.PI/2),metal,[0,-12,-.1],'Finger concealed fixed retaining shank');mesh(host.body,new THREE.CircleGeometry(.5,6).rotateY(Math.PI),materials.cavity(),[0,-12,-3.61],'Finger recessed screw drive');return{head,shank};}
export function buildFinger(host){const parts=addCadParts(host,data,{shell:materials.plastic(0xe8e9e3,{roughness:.82})}),pcb=adapter(host),sensor=pickup(host),input=grove(host),fixing=retaining(host),back=slab(host.body,...spec.labels.back.size,.04,.08,spec.labels.back.position,materials.plastic(0xdfdfd5,{roughness:.88}),[],0);back.name='Finger physical rear adhesive film seated on native label recess';back.userData={role:'physical-label-substrate',face:'back'};const anchor=host.add(new Component({id:'sensor',label:'FPC1020A fixed capacitive face appearance anchor',position:spec.sensor.position,meta:{role:'visual-anchor',part:'FPC1020A',scope:'Passive fixed surface anchor only;no fingerprint,identity,image,template,scan,recognition,touch wake,UART,power or electrical commands'}}));host.fingerAssembly={parts,pcb,sensor,input,fixing,labels:{back},anchor};host.unitStickers=addStickers(host);}
